"""Writes docs/REPORT_FACTS.md from the experiment JSON files (single human-readable copy of every number used in the documents).

    python -m scripts.docs.make_report_facts      (from 8.ProjectCode)
"""
import os

from . import facts as F


def row(*c):
    return "| " + " | ".join(str(x) for x in c) + " |"


def pc(x, d=2):
    return f"{x * 100:.{d}f} %"


def build():
    o = []
    a = o.append
    D, B, N, G, S, T, A = F.DATA, F.BASE, F.FIN, F.GAN, F.SYN, F.DET, F.APIM
    a(f"# {F.PRODUCT} (CSDS-A-A16) - REPORT FACTS\n")
    a("Generated by `scripts/docs/make_report_facts.py` from `experiments/**/metrics.json` and `experiments/pytest_results.xml`. Every document quotes this file.\n")
    a("## 1. Batch\n")
    a(f"- Title: {F.FULL_TITLE}\n- Product name in the code and UI: **{F.PRODUCT}** (the batch prompt calls it AffectLens; the shipped code, README, API contract and UI all say Mosaic)")
    a("- Students: " + "; ".join(f"{n} ({r})" for n, r in F.STUDENTS))
    a(f"- Guide: {F.GUIDE} (the batch file carries the literal placeholder 'GUIDE NAME')\n- Base paper: {F.BASE_PAPER}")
    a("- Base paper facts: " + "; ".join(f"{k}: {v}" for k, v in F.BP.items()) + "\n")
    a("## 2. Architecture and code facts\n")
    a("- Backend `backend/app`: FastAPI 0.115 (requirements pin), SQLAlchemy/SQLite (`mosaic.db`), JWT (python-jose, HS256, 7-day expiry), bcrypt via passlib, PyTorch CPU, OpenCV Haar cascade `haarcascade_frontalface_default.xml`.")
    a("- Frontend `frontend/src`: Next.js 16.3.6, React 19.2.8, TypeScript, Tailwind 4, Framer Motion, GSAP, Lenis, Three.js (landing canvas), Recharts, zustand (persisted token), react-webcam.")
    a("- ML: `EmotionCNN` (4 conv blocks 32-64-128-128 with BatchNorm/ReLU/MaxPool, FC 2048-256, dropout 0.4, out_dim 7 or 18) - " + f"{N['parameters']:,} parameters at 18 outputs; `ConditionalGenerator` (ConvTranspose 100+7 -> 256-128-64-32-1, Tanh, 64x64) {G['generator_parameters']:,} parameters; `ConditionalDiscriminator` (conv 32-64-128-256 + 16-d condition projection).")
    a("- Input: 64x64 grayscale scaled to [-1, 1]; labels: 7 basic + 11 compound (Du, Tao and Martinez pairs) = 18 sigmoid outputs; decision rule in `inference.py`: argmax over all 18 sigmoid outputs gives `dominant`; basic and compound lists are returned sorted.")
    a("- Training (`app/ml`): stage 1 softmax CNN, Adam lr 1e-3, batch 256, 5 epochs, class-weighted CE; cEmoGAN: Adam lr 2e-4 betas (0.5, 0.999), batch 64, 10 epochs on 400 images per class (2,800), label smoothing 0.9; final classifier: init from stage-1 `features.*`, BCE-with-logits, Adam lr 5e-4, batch 256, 5 epochs, real 28,709 + synthetic 2,200 (200 per compound class, condition 0.5/0.5 on the two components, multi-hot target = both basics + the compound).")
    a("- Endpoints: `POST /api/auth/register` (201/409/422), `POST /api/auth/login` (200/401), `GET /api/auth/me`, `POST /api/analyze` (multipart `image`; auth optional; 200 even when no face is found), `GET /api/history?limit&offset`, `GET /api/history/{id}`, `DELETE /api/history/{id}` (204), `GET /api/health`, static `/api/media/thumbs/{id}.jpg`.")
    a("- Database tables: `users(id, name, email unique, password_hash, created_at)`, `analyses(id, user_id FK, created_at, face_detected, basic_emotions JSON, compound_emotions JSON, dominant JSON, thumbnail_path)`.")
    a("- Ports: code defaults 8000 (API) and 3000 (UI); during this run port 8000 was occupied by another product, so the API ran on 8116 and the UI was a production build (`next build` + `next start -p 3000`) with `NEXT_PUBLIC_API_URL=http://localhost:8116/api`.\n")
    a("## 3. Dataset\n")
    a(f"- Source: Hugging Face `Jeneral/fer-2013` (FER2013 as pickled lists of JPEG bytes, tagged apache-2.0 on the Hub; original data: Goodfellow et al., ICML 2013 workshop / Neural Networks 2015). Native size 48x48 grayscale, resized to {D['model_input']}x{D['model_input']} for the CNN.")
    a(f"- Rows: train {D['n_train']:,}, test {D['n_test']:,} (the official FER2013 train / public+private test partition as shipped by the mirror; no separate validation split - the test set is also used for the per-epoch validation printout, never for model selection).")
    a(row("Class", *F.BASIC))
    a(row(*["---"] * 8))
    a(row("train", *[f"{D['class_counts']['train'][k]:,}" for k in F.BASIC]))
    a(row("test", *[f"{D['class_counts']['test'][k]:,}" for k in F.BASIC]))
    a(f"- Majority-class baseline on test (always 'happy'): {pc(D['test_majority_baseline'])}. No compound-emotion ground truth exists in FER2013; the 11 compound outputs have **no real test labels**.\n")
    a("## 4. Training logs written by the product (`backend/checkpoints/training_log.txt`)\n")
    a("- `[stage1 basic classifier] train=28709 test=7178 epochs=5 final_val_acc=0.5056`\n- `[cEmoGAN] samples=2800 epochs=10 final_d_loss=0.7731 final_g_loss=3.7240`")
    a("- `[final 18-label classifier] real=28709 synthetic=2200 epochs=5 ... final_basic_val_acc=0.5814` (this stage had **not** been run when the batch was received: `classifier_final.pt` was missing, so the API reported `model_loaded: false`; it was trained during this documentation run with the unchanged `train_final_classifier.py`, 10 min 37 s on a shared CPU).\n")
    a("## 5. Basic-emotion results on the FER2013 test set (7,178 images)\n")
    a(row("Model", "Accuracy", "Macro-F1", "Weighted-F1"))
    a(row(*["---"] * 4))
    a(row("Stage-1 single-label softmax CNN (shipped checkpoint, 5 epochs)", pc(B["accuracy"]), f"{B['macro_f1']:.4f}", f"{B['weighted_f1']:.4f}"))
    a(row("Final 18-label multi-label CNN (shipped, argmax over 7 basic outputs)", pc(N["accuracy"]), f"{N['macro_f1']:.4f}", f"{N['weighted_f1']:.4f}"))
    a("\nPer-class (final model): " + "; ".join(f"{k} P {v['precision']:.3f} R {v['recall']:.3f} F1 {v['f1']:.3f} (n={v['support']})" for k, v in N["per_class"].items()))
    a("\nPer-class F1 (baseline): " + "; ".join(f"{k} {v['f1']:.3f}" for k, v in B["per_class"].items()))
    a("\nConfusion matrix, final model (rows = true, columns = predicted; order " + ", ".join(F.BASIC) + "): " + str(N["confusion_matrix"]))
    a("\nConfusion matrix, baseline: " + str(B["confusion_matrix"]) + "\n")
    a("### Seeded ablation: does the GAN data help? (same init, 5 epochs, seeds 1-3; test accuracy / macro-F1)\n")
    a(row("Variant", "Seeds", "Accuracy (mean ± std)", "Macro-F1 (mean ± std)", "Real-test compound max-prob (mean)", "Synthetic hold-out compound AUC"))
    a(row(*["---"] * 6))
    for lab, pre in (("Real data only (18 outputs, compound bits always 0)", "real_only"), ("Real + 200 synthetic per compound class (the product recipe)", "synth")):
        acc, f1 = F.abl_vals(pre, "accuracy"), F.abl_vals(pre, "macro_f1")
        if not acc:
            continue
        mx = [x["compound_on_real_test"]["mean_top_compound_confidence"] for x in (F.ABL[f"{pre}_s{s}"] for s in (1, 2, 3) if f"{pre}_s{s}" in F.ABL)]
        au = [x["synthetic_holdout_thr0.5"].get("compound_roc_auc_macro") for x in (F.ABL[f"{pre}_s{s}"] for s in (1, 2, 3) if f"{pre}_s{s}" in F.ABL)]
        au = [v for v in au if v is not None]
        a(row(lab, len(acc), F.mstd(acc), F.mstd(f1, 2, False) if False else F.mstd(f1), f"{sum(mx) / len(mx):.5f}", f"{sum(au) / len(au):.3f}" if au else "n/a (no compound labels in training)"))
    for n, lab in (("synth50_s1", "Synthetic 50 per compound class (seed 1)"), ("synth800_s1", "Synthetic 800 per compound class (seed 1)")):
        if n in F.ABL:
            x = F.ABL[n]
            a(row(lab, 1, pc(x["accuracy"]), f"{x['macro_f1'] * 100:.2f}", f"{x['compound_on_real_test']['mean_top_compound_confidence']:.5f}", f"{x['synthetic_holdout_thr0.5']['compound_roc_auc_macro']:.3f}"))
    a("")
    a("## 6. Compound-emotion behaviour (no real ground truth exists)\n")
    c = N["compound_on_real_test"]
    a(f"- Shipped model on the {c['n']:,} real test faces: maximum compound probability averages {c['mean_top_compound_confidence']:.5f}; images with any compound output >= 0.3: {pc(c['any_compound_ge_0.3'])}; >= 0.5: {pc(c['any_compound_ge_0.5'])}; dominant (argmax of 18) is a compound: {pc(c['dominant_is_compound'])}.")
    a(f"- Mean compound score when the true basic label is a component of the compound {c['mean_score_true_basic_is_component']:.6f} versus not a component {c['mean_score_true_basic_not_component']:.6f} (no separation). Top compound contains the true basic label {pc(c['top_compound_contains_true_basic'])} of the time (chance {pc(c['chance_top_compound_contains_true_basic'])}).")
    a("- Synthetic hold-out (1,100 freshly generated compound faces, 100 per class, seed 12345; labels = the two component bits + the compound bit):\n")
    a(row("Threshold", "Micro-F1", "Macro-F1", "Exact-match ratio", "Compound recall", "Compound ROC-AUC (macro)"))
    a(row(*["---"] * 6))
    for t, v in S["final_model"].items():
        a(row(t, f"{v['micro_f1']:.3f}", f"{v['macro_f1']:.3f}", f"{v['exact_match_ratio']:.3f}", pc(v["compound_recall"], 1), f"{v['compound_roc_auc_macro']:.3f}"))
    if "real_only_control" in S:
        r = S["real_only_control"]
        a(f"\n- Control (same architecture trained on real data only) on the same hold-out at 0.5: micro-F1 {r['micro_f1']:.3f}, compound recall {pc(r['compound_recall'], 1)}, compound ROC-AUC {r['compound_roc_auc_macro']:.3f}.")
    a(f"- Dominant label is the correct compound on the hold-out: {pc(S['final_model']['0.5']['dominant_is_correct_compound'])}.\n")
    a("## 7. cEmoGAN fidelity (shipped generator, 10 epochs)\n")
    a(f"- Training-log losses: D 0.7731, G 3.7240. Generator parameters {G['generator_parameters']:,}.")
    a("- Conditional accuracy of the stage-1 classifier on 500 generated faces per basic class: " + ", ".join(f"{k} {pc(v['stage1_accuracy_on_generated'], 1)}" for k, v in G["basic"].items()) + f" - mean {pc(G['mean_basic_conditional_accuracy'], 1)} (chance 14.3 %).")
    a("- Compound conditions (500 each): " + "; ".join(f"{k}: top-1 in pair {pc(v['stage1_top1_in_pair'], 0)}, top-2 = pair {pc(v['stage1_top2_equals_pair'], 0)}" for k, v in G["compound"].items()) + f". Means: top-1 in pair {pc(G['mean_compound_top1_in_pair'], 1)} (chance {pc(G['chance_top1_in_pair'], 1)}), top-2 = pair {pc(G['mean_compound_top2_equals_pair'], 1)} (chance {pc(G['chance_top2_equals_pair'], 1)}).")
    fr = G["frechet_distance_stage1_features"]
    a(f"- Fréchet distance in the stage-1 CNN's 256-d feature space against 2,800 real training faces: generated basic {fr['generated_basic_vs_real_train_subset']:.1f}, generated compound {fr['generated_compound_vs_real_train_subset']:.1f}, real test faces {fr['real_test_vs_real_train_subset']:.1f} (reference). Not an Inception FID and not comparable with the base paper's FID.")
    a(f"- Pixel-wise standard deviation within a class: generated {G['pixelwise_std_within_class']['generated']:.1f}, real {G['pixelwise_std_within_class']['real']:.1f}.\n")
    a("## 8. Face detection and the serving path\n")
    a("Haar detection rate on 1,000 random FER2013 test images, by bicubic upscale factor of the native 48x48 pixels: " + ", ".join(f"{k[len('haar_detection_rate_scale_'):]} {pc(v, 1)}" for k, v in T.items() if k.startswith("haar_detection")) + ".")
    a(f"- On the {T['detected_at_3x']} images detected at 3x, the final model's accuracy through the product path (Haar crop -> 64x64) is {pc(T['accuracy_via_haar_crop_on_detected'], 1)} versus {pc(T['accuracy_direct_64px_on_same_images'], 1)} when the same images are resized directly (training-style framing).\n")
    a("## 9. Tests\n")
    if F.TESTS:
        t = F.TESTS
        a(f"- `backend/tests` (pytest, TestClient with a temporary SQLite database): {t['tests']} tests, {t['failures']} failures, {t['errors']} errors, {t['skipped']} skipped, {t['seconds']:.1f} s. Files: `test_units.py` (taxonomy, security, shapes, preprocessing, synthesis labels) and `test_api.py` (auth, analyze, history privacy, characterised defects).")
        a("- Tests that characterise defects: no face -> 200 (contract says 422); undecodable upload -> 500.")
    a("")
    a("## 10. API latency and abuse probes (`scripts/measure_api.py`, 127.0.0.1)\n")
    if A:
        a(row("Request", "n", "p50 ms", "p95 ms", "max ms"))
        a(row(*["---"] * 5))
        for l in A["latency"]:
            a(row(l["label"], l["n"], f"{l['p50_ms']:.1f}", f"{l['p95_ms']:.1f}", f"{l['max_ms']:.1f}"))
        a(f"\n- Probes {A['probes_ok']}/{A['probes_total']} as expected; API healthy afterwards: {A['healthy_after_probes']}.")
        for p in A["probes"]:
            if not p["ok"]:
                a(f"- Unexpected: {p['name']} -> {p['status']} ({p['body'][:80]})")
        a(f"- CORS: allow-origin for localhost:3000 = {A['cors_listed_origin_allow_origin_header']}, for an unlisted origin = {A['cors_unlisted_origin_allow_origin_header']}.")
    a("\n## 11. Known product defects found while measuring (all left unchanged)\n")
    a("1. Compound outputs are inert on real faces and cannot rank synthetic compound classes (see section 6); `dominant` is therefore never a compound label.\n2. The cEmoGAN does not obey its condition (section 7).\n3. `ResultsView` uses `result.thumbnail_url` directly, a relative path that resolves against the UI origin, so the thumbnail shows a broken image; `thumbnailUrl()` in `lib/api.ts` is never applied there.\n4. `/app/history/[id]` exists but nothing in the UI links to it.\n5. A hard reload of a protected route (`/app`) lands on `/login` even with a stored token (the guard runs before the persisted store is read).\n6. `POST /api/analyze` answers 200 with `face_detected: false` where `API_CONTRACT.md` says 422; undecodable files cause HTTP 500.\n7. Training/serving mismatch: training faces are 48x48 aligned FER crops, serving uses a Haar crop of the photo.\n8. `requirements.txt` pins `bcrypt==4.0.1` for a reason: bcrypt 5 breaks passlib hashing (seen in the first test run).\n9. No `run.bat`/`setup.bat`/`.env.example` exist in the code folder; ports are 8000/3000 not the batch prompt's 8116/5116.\n")
    a("## 12. Screenshot inventory (`docs/screenshots`, 1440x900, real FER2013 faces and cEmoGAN output)\n")
    sp = os.path.join(F.SHOTS)
    for f in sorted(os.listdir(sp)):
        if f.endswith(".png"):
            a(f"- `{f}`")
    a("- Inputs used: `docs/screenshots/inputs/*.jpg|png` (real FER2013 test faces upscaled 5x onto a 640x360 canvas; `gan_*` files are generator output; `native48_happy.png` is an un-upscaled 48x48 FER face).")
    return "\n".join(o) + "\n"


def main():
    p = os.path.join(F.DOCS, "REPORT_FACTS.md")
    open(p, "w", encoding="utf-8").write(build())
    print("wrote", p)


if __name__ == "__main__":
    main()
